    },
    {
      "#": 3,
      "status": "confirmed",
      "protected_subject": null,
      "reason": "Precondition is a missing or unreadable certifi bundle; my repro with a stub certifi.where() returning /nonexistent/cacert.pem made 'import requests' raise FileNotFoundError at adapters.py:76-78 (previously the failure came only at verify=True request time via cert_verify's OSError), and incidence of missing bundles in deployments was not measured."
    }
  ]
}
E
